<template>
  <section class="orbital-map" aria-label="插件能力星图">
    <div class="orbit-toolbar"><span>CAPABILITY ORBIT / 能力轨道</span><button type="button" :aria-pressed="paused" @click="paused = !paused">{{ paused ? '开启旋转' : '暂停旋转' }}</button></div>
    <div class="orbit-stage" :class="{ 'is-paused': paused || focused || hovered || reduced || !visible }" @mouseenter="hovered = true" @mouseleave="hovered = false" @focusin="focused = true" @focusout="focused = $event.currentTarget.contains($event.relatedTarget)">
      <div class="orbit-grid" aria-hidden="true" /><div class="orbit-ring ring-inner" aria-hidden="true" /><div class="orbit-ring ring-outer" aria-hidden="true" />
      <div class="orbit-core"><span class="core-mark">S<span>∞</span></span><strong>SMARTOPS</strong><small>能力可组合</small></div>
      <div class="orbit-rotor">
        <div v-for="(item, index) in items" :key="item.id" class="node-anchor" :style="{ '--angle': `${index / Math.max(items.length, 1) * 360 - 90}deg` }">
          <div class="node-upright"><button type="button" class="orbit-node" :class="{ selected: selectedId === item.id, related: relatedIds.includes(item.id), enabled: item.enabled }" :aria-label="`查看${item.name}`" :aria-pressed="selectedId === item.id" @click="emit('select', item.id); paused = true"><component :is="icons[item.icon] || Grid" aria-hidden="true" /><span class="node-title">{{ item.shortName }}</span><span class="node-state">{{ item.enabled ? '已启用' : item.installed ? '已停用' : '未添加' }}</span></button></div>
        </div>
      </div>
    </div>
    <footer><span><i />已启用入口</span><span>点击节点查看详情 · 悬停暂停</span></footer>
  </section>
</template>
<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'
import { Collection, Connection, Cpu, DataLine, DataAnalysis, Document, Grid, Monitor, View } from '@element-plus/icons-vue'
defineProps({ items: { type: Array, default: () => [] }, selectedId: { type: String, default: '' }, relatedIds: { type: Array, default: () => [] } })
const emit = defineEmits(['select'])
const icons = { Collection, Connection, Cpu, DataLine, DataAnalysis, Document, Grid, Monitor, View }
const paused = ref(false), hovered = ref(false), focused = ref(false), reduced = ref(false), visible = ref(true)
let mq
const syncMotion = () => { reduced.value = mq.matches }
const syncVisible = () => { visible.value = !document.hidden }
onMounted(() => { mq = matchMedia('(prefers-reduced-motion: reduce)'); syncMotion(); syncVisible(); mq.addEventListener('change', syncMotion); document.addEventListener('visibilitychange', syncVisible) })
onBeforeUnmount(() => { mq?.removeEventListener('change', syncMotion); document.removeEventListener('visibilitychange', syncVisible) })
</script>
<style scoped>
.orbital-map{position:relative;min-width:0;overflow:hidden;background:var(--smart-surface);border:1px solid var(--smart-border);border-radius:18px}.orbit-toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:20px 24px;color:var(--smart-muted);font:10px var(--font-mono);letter-spacing:.08em}.orbit-toolbar button{background:transparent;border:1px solid var(--smart-border);color:var(--smart-text);border-radius:6px;padding:8px 12px;min-height:40px;cursor:pointer}.orbit-stage{--radius:clamp(105px,16vw,172px);height:470px;position:relative;isolation:isolate}.orbit-grid{position:absolute;inset:0;background-image:radial-gradient(var(--smart-border) 1px,transparent 1px);background-size:24px 24px;mask-image:radial-gradient(ellipse,#000,transparent 70%)}.orbit-ring{position:absolute;left:50%;top:50%;border:1px solid var(--smart-border);border-radius:50%;transform:translate(-50%,-50%);pointer-events:none}.ring-outer{width:calc(var(--radius)*2);height:calc(var(--radius)*2)}.ring-inner{width:calc(var(--radius)*1.3);height:calc(var(--radius)*1.3);border-style:dashed}.orbit-core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:112px;height:112px;border:1px solid var(--smart-primary-strong);border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--smart-bg);box-shadow:0 0 55px color-mix(in srgb,var(--smart-primary) 17%,transparent)}.core-mark{font:30px var(--font-display);color:var(--smart-primary-strong)}.core-mark span{font-size:24px}.orbit-core strong{font:10px var(--font-mono);letter-spacing:.12em;margin-top:4px}.orbit-core small{font-size:10px;color:var(--smart-muted);margin-top:6px}.orbit-rotor{position:absolute;inset:0;animation:orbit-turn 100s linear infinite}.node-anchor{position:absolute;left:50%;top:50%;width:0;height:0;transform:rotate(var(--angle)) translateX(var(--radius)) rotate(calc(-1 * var(--angle)))}.node-upright{width:0;height:0;animation:orbit-turn 100s linear reverse infinite}.orbit-node{position:absolute;left:-23px;top:-23px;display:grid;place-items:center;width:46px;height:46px;border-radius:14px;border:1px solid var(--smart-border);color:var(--smart-muted);background:var(--smart-bg);cursor:pointer;transition:background 160ms,border-color 160ms,box-shadow 160ms}.orbit-node svg{width:21px;height:21px}.orbit-node.enabled{color:var(--smart-primary-strong);border-color:var(--smart-primary-strong)}.orbit-node.selected{background:var(--smart-primary-strong);color:var(--smart-bg);box-shadow:0 0 0 6px color-mix(in srgb,var(--smart-primary) 12%,transparent)}.orbit-node.related{border-style:dashed;border-color:var(--smart-warning)}.node-title{position:absolute;top:52px;color:var(--smart-text);font-size:11px;white-space:nowrap;max-width:105px;overflow:hidden;text-overflow:ellipsis}.node-state{position:absolute;top:70px;color:var(--smart-muted);font-size:9px;white-space:nowrap}.is-paused .orbit-rotor,.is-paused .node-upright{animation-play-state:paused}button:focus-visible{outline:2px solid var(--smart-primary-strong);outline-offset:5px}.orbital-map footer{display:flex;justify-content:space-between;gap:10px;padding:18px 24px;border-top:1px solid var(--smart-border);color:var(--smart-muted);font-size:10px}.orbital-map footer i{display:inline-block;width:5px;height:5px;border-radius:50%;background:var(--smart-primary-strong);margin-right:6px}@keyframes orbit-turn{to{transform:rotate(360deg)}}@media(max-width:767px){.orbit-stage{height:350px;--radius:112px}.orbit-core{width:84px;height:84px}.core-mark{font-size:22px}.orbit-core strong{font-size:8px}.orbit-toolbar{padding:14px}.orbital-map footer{padding:16px 14px;font-size:9px}.orbit-node{width:40px;height:40px;left:-20px;top:-20px;border-radius:12px}.node-title{font-size:10px;top:44px}.node-state{display:none}}@media(prefers-reduced-motion:reduce){.orbit-rotor,.node-upright{animation:none}.orbit-node{transition:none}}
</style>

